 -> /about", "Headquarters Honolulu, Hawaii -> db"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "Grand Hawaii Electric provides fast, reliable electrical services in Honolulu and the surrounding areas.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='grand-hawaii-electric-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='The company does not disclose its founding year or ownership structure, but it presents itself as a contract development and manufacturing organization focused on sterile injectable fill-finish.

