ons -> /", "Offers portable solar power (Jackery) -> /", "Offers cold storage systems -> /", "Provides storm damage repair -> /", "Provides financing assistance -> /", "Member since 2022 -> /"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "Great Plains Renewables is a Nebraska based seller and installer of renewable energy and seller of solar battery backup solutions.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='great-plains-renewables' AND approved AND profile IS NULL;
